#if UNITY_EDITOR
using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class PrisonCctvCheck {
static int step;static float wait;static bool running;static double deadline;
const string Log="Logs/Prison-cctv-check.txt";
static PrisonCctvCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("CctvCheck",false)){SessionState.SetBool("CctvCheck",false);running=true;step=0;deadline=EditorApplication.timeSinceStartup+160;}};}
static void Check(bool b,string t){File.AppendAllText(Log,(b?"PASS ":"FAIL ")+t+"\n");if(!b)throw new Exception(t);}
static void Place(PlayerCombat p,Vector3 at,Vector3 look){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=at;cc.enabled=true;p.View.transform.LookAt(look);p.GetComponentInChildren<CameraMove>().SyncViewFromTransform();Physics.SyncTransforms();}
static void Tick(){
if(!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&File.Exists("Temp/PrisonCctvCheck")){File.Delete("Temp/PrisonCctvCheck");File.WriteAllText(Log,"Assisted stage entry and travel; actual mission coroutines and interaction checks.\n");SessionState.SetBool("CctvCheck",true);EditorApplication.EnterPlaymode();return;}
if(!running||!EditorApplication.isPlaying)return;
try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timeout stage "+step);
var m=Object.FindFirstObjectByType<PrisonCctvMission>();if(!m)return;var o=m.office;var p=o.previous.previous.prison.player;var e=o.evidence;
if(step==0){step=1;wait=Time.time+2;return;}if(Time.time<wait)return;
if(step==1){o.previous.previous.prison.introduction.DeveloperComplete();Object.FindFirstObjectByType<PrisonChickenMission>().DeveloperComplete();typeof(PrisonKeysMission).GetProperty("State").SetValue(o.previous,PrisonKeysMission.Stage.Complete);o.previous.warden.gameObject.SetActive(true);o.previous.warden.enabled=false;o.previous.warden.GetComponent<NPCControl>().ExternalControl=true;typeof(PrisonOfficeEvidence).GetProperty("Discovered").SetValue(e,3);m.dialogue=Object.Instantiate(m.dialogue);m.dialogue.lineSeconds=.15f;step=2;wait=Time.time+1;return;}
if(step==2){Place(p,e.wardenStand.position+e.wardenStand.forward*1.7f+Vector3.up*1.1f,e.wardenStand.position+Vector3.up);Check(e.Inspect(3),"blackmail starts");step=3;wait=Time.time+15;return;}
if(step==3){Check(e.Authorized&&!e.Busy&&p.CanAct,"blackmail restores control");var cam=o.previous.camera;cam.transform.position=m.restraint.seat.position+new Vector3(2.3f,1.6f,1);cam.transform.LookAt(m.restraint.seat.position+Vector3.up);PrisonChickenCheck.Capture(cam,"Logs/Prison-cctv-warden.png");Check(m.restraint.Bound&&m.restraint.ropes.activeSelf,"warden bound and asleep");Place(p,o.points[0].transform.position+new Vector3(0,1.1f,-1),o.points[0].transform.position);Check(o.points[0].TryInteract(),"uniform drawer opens");step=4;wait=Time.time+1;return;}
if(step==4){Check(o.points[0].TryInteract(),"uniform pickup");step=5;wait=Time.time+4;return;}
if(step==5){Check(o.Complete&&m.State==PrisonCctvMission.Stage.Change,"uniform completes office without vehicle key/password");Place(p,m.legacyEscape.changePoint.position+Vector3.up,m.legacyEscape.changePoint.position);Check(m.Interact(),"disguise starts");step=6;wait=Time.time+2;return;}
if(step==6){Check(m.State==PrisonCctvMission.Stage.Infiltrate&&m.legacyEscape.Disguised&&p.CanAct,"disguise and control");Place(p,m.entry.position+Vector3.up,m.entry.position);Check(m.Interact(),"security door opens");step=7;wait=Time.time+1.2f;return;}
if(step==7){Check(m.State==PrisonCctvMission.Stage.Disable,"console stage");Place(p,m.console.position+new Vector3(0,0,1.4f),m.console.position);step=8;wait=Time.time+.2f;return;}
if(step==8){p.View.transform.LookAt(m.console.position);p.GetComponentInChildren<CameraMove>().SyncViewFromTransform();if(m.wirePanel&&!m.CamerasDisabled){if(!m.wirePanel.Playing)m.Interact();else if(m.wirePanel.Ready)m.wirePanel.Choose(m.wirePanel.correctWire);}else m.Operate(true,.1f);if(Time.frameCount%120==0){File.AppendAllText(Log,"CONSOLE "+m.State+" progress="+m.Progress+" channels="+m.Channels+" can="+p.CanAct+" player="+p.transform.position+" view="+p.View.transform.position+"\n");foreach(var hit in Physics.RaycastAll(p.View.transform.position,(m.console.position-p.View.transform.position).normalized,Vector3.Distance(m.console.position,p.View.transform.position)))File.AppendAllText(Log,"HIT "+hit.transform.name+" "+hit.distance+"\n");}if(!m.CamerasDisabled)return;PrisonChickenCheck.Capture(p.View,"Logs/Prison-cctv-console.png");Check(m.Channels==3&&Array.TrueForAll(m.monitors,x=>x.Disabled),"all feeds disabled");Check(p.CanAct&&m.State==PrisonCctvMission.Stage.Leave,"leave objective and controls");Place(p,m.safePoint.position+Vector3.up,m.safePoint.position+Vector3.forward);step=9;wait=Time.time+.5f;return;}
if(step==9){PrisonChickenCheck.Capture(p.View,"Logs/Prison-cctv-complete.png");Check(m.State==PrisonCctvMission.Stage.Complete,"outside rendezvous complete");Check(m.legacyEscape.State==PrisonEscapeMission.Stage.Waiting,"old escape did not auto start");Check(o.previous.previous.prison.introduction.mingi.Following,"Mingi following");typeof(PrisonCctvMission).GetProperty("State").SetValue(m,PrisonCctvMission.Stage.Infiltrate);m.watch.gameObject.SetActive(true);Place(p,new Vector3(-36.7f,1.1f,-27.5f),m.watch.transform.position+Vector3.up);step=10;return;}
if(step==10){if(Time.frameCount%90==0){File.AppendAllText(Log,"WATCH "+m.watch.transform.position+" player "+p.transform.position+" view "+p.View.transform.position+" seen "+m.watch.CanSee(p)+" suspicion "+m.Suspicion+" can "+p.CanAct+"\n");var eye=m.watch.transform.position+Vector3.up*1.55f;foreach(var h in Physics.RaycastAll(eye,(p.View.transform.position-eye).normalized,Vector3.Distance(eye,p.View.transform.position)))File.AppendAllText(Log,"WATCH HIT "+h.transform.name+"\n");}if(m.Attempts==0||m.Busy)return;Check(m.State==PrisonCctvMission.Stage.Infiltrate&&m.Channels==0,"real guard sight detection and checkpoint retry");Check(m.restraint.Bound&&o.HasUniforms&&p.CanAct,"retry preserves uniform, restrained warden and controls");Check(Vector3.Distance(p.transform.position,m.checkpoint.position)<2,"retry returns to security entrance");m.DeveloperComplete();Check(m.State==PrisonCctvMission.Stage.Complete&&p.CanAct,"CCTV developer skip");File.AppendAllText(Log,"FINISHED\n");running=false;EditorApplication.ExitPlaymode();}
}catch(Exception ex){File.AppendAllText(Log,ex.ToString());running=false;EditorApplication.ExitPlaymode();}
}
}}
#endif
